import Foundation

/// `calculation` fields and business functions: ports of forms-core's
/// `calculation.ts` and `business-function.ts`.
public enum BdCalculation {
    public struct Outcome: Sendable, Hashable {
        public let ok: Bool
        public let value: BdJSON?
        public let outputs: [String: BdJSON]?
        public let error: String?
    }

    public struct FunctionRun: Sendable, Hashable {
        public let ok: Bool
        public let outputs: [String: BdJSON]
        /// `scope/key: reason` per problem.
        public let issues: [String]
    }

    /// A form value as a formula input: blank is "no value", an array reads
    /// as its comma-joined text, everything else passes through.
    static func formulaValue(_ raw: BdJSON?) -> BdJSON? {
        guard let raw, !BdJSON.isBlank(raw) else { return nil }
        if case .array = raw { return .string(BdJS.string(raw)) }
        return raw
    }

    public static func compute(
        _ config: BdFormField.CalculationConfig,
        resolve: (String) -> BdJSON?,
        functionsById: [String: BdBusinessFunction] = [:],
        userFunctions: [String: BdFormula.UserFunction] = [:]
    ) -> Outcome {
        let bindings = config.inputMap ?? []
        if config.mode == "function" {
            guard let id = config.functionId, let def = functionsById[id] else {
                return Outcome(ok: false, value: nil, outputs: nil, error: "Referenced function not found.")
            }
            var raw: [String: BdJSON?] = [:]
            for b in bindings { raw[b.variable] = resolve(b.fieldId) }
            let run = runFunction(def, inputs: raw, userFunctions: userFunctions)
            let key = config.outputKey ?? def.outputs.first?.key
            let value = key.flatMap { run.outputs[$0] }
            return Outcome(
                ok: run.ok,
                value: value,
                outputs: run.outputs,
                error: run.ok ? nil : run.issues.joined(separator: "; ")
            )
        }
        guard let formula = config.formula?.trimmingCharacters(in: BdJS.jsWhitespace), !formula.isEmpty else {
            return Outcome(ok: false, value: nil, outputs: nil, error: "No formula.")
        }
        var vars: [String: BdJSON?] = [:]
        for b in bindings { vars[b.variable] = formulaValue(resolve(b.fieldId)) }
        switch BdFormula.run(formula, vars: vars, functions: userFunctions) {
        case .ok(let v): return Outcome(ok: true, value: v, outputs: nil, error: nil)
        case .error(let e): return Outcome(ok: false, value: nil, outputs: nil, error: e)
        }
    }

    /// Prefix + value + suffix, with fixed decimals for numbers.
    public static func format(_ value: BdJSON?, display: BdFormField.CalculationConfig.Display?) -> String {
        guard let value, !value.isNull else { return "" }
        let body: String
        switch value {
        case .number(let n) where display?.decimals != nil && n.isFinite:
            body = BdJS.toFixed(n, display?.decimals ?? 0)
        case .object, .array:
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
            body = (try? encoder.encode(value)).flatMap { String(data: $0, encoding: .utf8) } ?? ""
        default:
            body = BdJS.string(value)
        }
        return (display?.prefix ?? "") + body + (display?.suffix ?? "")
    }

    nonisolated(unsafe) static let isoDate = #/^\d{4}-\d{2}-\d{2}([T ].*)?$/#

    static func coerce(_ value: BdJSON, _ type: String) -> Swift.Result<BdJSON, CoerceFailure> {
        switch type {
        case "any": return .success(value)
        case "object":
            if case .object = value { return .success(value) }
            return .failure(.init(reason: "expected an object"))
        case "number":
            let n = value.doubleValue ?? BdJS.number(value)
            return n.isNaN ? .failure(.init(reason: "not a number")) : .success(.number(n))
        case "boolean":
            switch value {
            case .bool: return .success(value)
            case .string("true"), .number(1): return .success(.bool(true))
            case .string("false"), .number(0): return .success(.bool(false))
            default: return .failure(.init(reason: "not a boolean"))
            }
        case "date":
            let s = BdJS.string(value)
            if s.firstMatch(of: isoDate) != nil, BdDates.parseInstant(s) != nil { return .success(.string(s)) }
            return .failure(.init(reason: "not a date"))
        default:
            if case .string = value { return .success(value) }
            return .success(.string(BdJS.string(value)))
        }
    }

    struct CoerceFailure: Error { let reason: String }

    static func matches(_ value: BdJSON, _ type: String) -> Bool {
        switch type {
        case "any": return true
        case "number": if case .number(let n) = value { return !n.isNaN } else { return false }
        case "text": return value.stringValue != nil
        case "boolean": return value.boolValue != nil
        case "object": return value.objectValue != nil
        case "date":
            guard let s = value.stringValue else { return false }
            return s.firstMatch(of: isoDate) != nil
        default: return false
        }
    }

    /// Run a business function: coerce and default its inputs, then evaluate
    /// each output in order (later outputs can read earlier ones), falling
    /// back where an output fails or comes out the wrong type.
    public static func runFunction(
        _ def: BdBusinessFunction,
        inputs raw: [String: BdJSON?],
        userFunctions: [String: BdFormula.UserFunction] = [:]
    ) -> FunctionRun {
        var issues: [String] = []
        var vars: [String: BdJSON?] = [:]
        for input in def.inputs {
            let value = raw[input.key] ?? nil
            if value == nil || BdJSON.isBlank(value) {
                if let d = input.default {
                    vars[input.key] = d
                } else if input.required == true {
                    issues.append("input/\(input.key): required value is missing")
                }
                continue
            }
            switch coerce(value!, input.type) {
            case .success(let v): vars[input.key] = v
            case .failure(let f): issues.append("input/\(input.key): \(f.reason)")
            }
        }
        var outputs: [String: BdJSON] = [:]
        for out in def.outputs {
            let r = BdFormula.run(out.formula, vars: vars, functions: userFunctions)
            func fallback(_ reason: String) {
                if let fb = out.fallback {
                    outputs[out.key] = fb
                    vars[out.key] = fb
                } else {
                    issues.append("output/\(out.key): \(reason)")
                }
            }
            switch r {
            case .error(let e):
                fallback(e)
            case .ok(let v):
                if matches(v, out.type) {
                    outputs[out.key] = v
                    vars[out.key] = v
                } else {
                    fallback("expected \(out.type)")
                }
            }
        }
        return FunctionRun(ok: issues.isEmpty, outputs: outputs, issues: issues)
    }
}
